import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import Calendar from 'react-calendar';
import 'react-calendar/dist/Calendar.css';

const API_BASE_URL = window.location.hostname === 'localhost'
    ? 'http://localhost:3001'
    : 'https://requena-backend-production.up.railway.app';

const EmployeeDashboard = () => {
  const navigate = useNavigate();
  const [user, setUser] = useState(null);
  const [vacationDays, setVacationDays] = useState(0);
  const [hasCheckedIn, setHasCheckedIn] = useState(false);
  const [hasCheckedOut, setHasCheckedOut] = useState(false);
  const [loading, setLoading] = useState(false);
  const [selectedDates, setSelectedDates] = useState([]);
  const [showCalendar, setShowCalendar] = useState(false);
  const [locationError, setLocationError] = useState(null);
  const [usedDates, setUsedDates] = useState([]);

  useEffect(() => {
    const storedUser = JSON.parse(localStorage.getItem('user'));
    if (!storedUser) {
      navigate('/login');
    } else {
      setUser(storedUser);
      fetchVacationDays(storedUser.id);
      checkIfCheckedIn(storedUser.id);
      checkIfCheckedOut(storedUser.id);
      fetchUsedDates(storedUser.id);
    }
  }, [navigate]);

  const fetchUsedDates = async (userId) => {
    try {
      const response = await fetch(`${API_BASE_URL}/users/${userId}/vacation-history`);
      const data = await response.json();
      const blocked = data
          .filter(r => r.status === 'approved' || r.status === 'pending')
          .map(r => r.vacation_date);
      setUsedDates(blocked);
    } catch (err) {
      console.error('Error al obtener fechas usadas:', err);
    }
  };

  const fetchVacationDays = async (userId) => {
    try {
      const response = await fetch(`${API_BASE_URL}/users/${userId}/vacation-days`);
      const data = await response.json();
      setVacationDays(data.vacation_days);
    } catch (error) {
      console.error('Error al obtener días de vacaciones:', error);
    }
  };

  const checkIfCheckedIn = async (userId) => {
    try {
      const response = await fetch(`${API_BASE_URL}/users/${userId}/checkIn-status`);
      const data = await response.json();
      setHasCheckedIn(data.checkedIn);
    } catch (error) {
      console.error('Error al verificar check-in:', error);
    }
  };

  const checkIfCheckedOut = async (userId) => {
    try {
      const response = await fetch(`${API_BASE_URL}/users/${userId}/checkOut-status`);
      const data = await response.json();
      setHasCheckedOut(data.alreadyCheckedOut);
    } catch (error) {
      console.error('Error al verificar check-out:', error);
    }
  };

  const handleCheck = async (type) => {
    setLoading(true);
    setLocationError(null);

    try {
      const position = await new Promise((resolve, reject) => {
        navigator.geolocation.getCurrentPosition(resolve, reject, {
          enableHighAccuracy: true,
          timeout: 10000
        });
      });

      const { latitude, longitude } = position.coords;
      const endpoint = type === 'checkin' ? 'checkIn' : 'checkOut';

      const response = await fetch(`${API_BASE_URL}/users/${endpoint}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          userId: user.id,
          latitude,
          longitude
        }),
      });

      if (!response.ok) throw new Error('Error al registrar');

      alert(`✅ ${type === 'checkin' ? 'Check-in' : 'Check-out'} registrado`);
      type === 'checkin' ? setHasCheckedIn(true) : setHasCheckedOut(true);
    } catch (error) {
      console.error(`Error en ${type}:`, error);
      setLocationError(
          error.code === error.PERMISSION_DENIED
              ? 'Debes permitir acceso a ubicación'
              : 'Error al obtener ubicación'
      );
    } finally {
      setLoading(false);
    }
  };

  const handleDateChange = (date) => {
    const dateStr = date.toISOString().split('T')[0];
    setSelectedDates(prev =>
        prev.includes(dateStr)
            ? prev.filter(d => d !== dateStr)
            : [...prev, dateStr]
    );
  };

  const handleVacationRequest = async () => {
    if (selectedDates.length === 0) return;

    const sortedDates = [...selectedDates].sort();
    try {
      setLoading(true);
      const response = await fetch(`${API_BASE_URL}/users/${user.id}/vacation-request-grouped`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        },
        body: JSON.stringify({ dates: sortedDates }),
      });

      const data = await response.json();
      if (!response.ok) throw new Error(data.message || 'Error en la solicitud');

      alert(`✅ ${sortedDates.length} días solicitados: ${sortedDates.join(', ')}`);
      setVacationDays(data.remainingDays);
      setUsedDates(prev => [...prev, ...sortedDates]);
      setSelectedDates([]);
      setShowCalendar(false);
    } catch (error) {
      alert(`❌ Error: ${error.message}`);
    } finally {
      setLoading(false);
    }
  };

  const tileDisabled = ({ date }) => {
    const dateStr = date.toISOString().split('T')[0];
    return usedDates.includes(dateStr) || date < new Date();
  };

  return (
      <div className="flex flex-col items-center py-10 bg-gray-100 min-h-screen">
        {user && <h1 className="text-3xl font-bold text-gray-800">Bienvenido, {user.name}</h1>}

        <div className="mt-6 bg-white p-6 rounded-lg shadow-md w-full max-w-md">
          <h2 className="text-xl font-semibold mb-4">Días disponibles: {vacationDays}</h2>

          {!hasCheckedIn && !hasCheckedOut && (
              <button
                  onClick={() => handleCheck('checkin')}
                  disabled={loading}
                  className={`w-full py-2 rounded-md text-white font-medium ${
                      loading ? 'bg-gray-400' : 'bg-green-500 hover:bg-green-600'
                  }`}
              >
                {loading ? 'Registrando...' : 'Registrar Check-in'}
              </button>
          )}

          {hasCheckedIn && !hasCheckedOut && (
              <button
                  onClick={() => handleCheck('checkout')}
                  disabled={loading}
                  className={`w-full py-2 rounded-md text-white font-medium ${
                      loading ? 'bg-gray-400' : 'bg-red-500 hover:bg-red-600'
                  }`}
              >
                {loading ? 'Registrando...' : 'Registrar Check-out'}
              </button>
          )}

          {locationError && (
              <p className="mt-2 text-red-500 text-sm">{locationError}</p>
          )}
        </div>

        <button
            onClick={() => setShowCalendar(!showCalendar)}
            disabled={vacationDays === 0}
            className={`mt-6 px-4 py-2 rounded-md ${
                vacationDays > 0
                    ? 'bg-blue-500 hover:bg-blue-600 text-white'
                    : 'bg-gray-300 text-gray-600 cursor-not-allowed'
            }`}
        >
          {showCalendar ? 'Cancelar' : 'Solicitar Vacaciones'}
        </button>

        {showCalendar && (
            <div className="mt-4 bg-white p-4 rounded-lg shadow-md">
              <Calendar
                  onChange={handleDateChange}
                  value={selectedDates.map(d => new Date(d))}
                  tileDisabled={tileDisabled}
                  selectRange={false}
                  className="border-0"
              />

              {selectedDates.length > 0 && (
                  <div className="mt-4">
                    <p className="mb-2">
                      Seleccionados: <strong>{selectedDates.length} días</strong>
                    </p>
                    <div className="flex gap-2">
                      <button
                          onClick={() => setSelectedDates([])}
                          className="px-3 py-1 bg-gray-300 rounded"
                      >
                        Limpiar
                      </button>
                      <button
                          onClick={handleVacationRequest}
                          disabled={loading}
                          className={`px-3 py-1 rounded text-white ${
                              loading ? 'bg-gray-400' : 'bg-green-500 hover:bg-green-600'
                          }`}
                      >
                        {loading ? 'Enviando...' : 'Enviar Solicitud'}
                      </button>
                    </div>
                  </div>
              )}
            </div>
        )}

        <button
            onClick={() => navigate('/employee/vacation-status')}
            className="mt-6 px-4 py-2 bg-purple-500 text-white rounded-md hover:bg-purple-600"
        >
          Ver Estado de Solicitudes
        </button>
      </div>
  );
};

export default EmployeeDashboard;
